<?php
require __DIR__ . '/bootstrap.php';method('GET');admin_required();try{$bookings=db()->query('SELECT booking_code AS id,pickup,dropoff,distance,instructions,vehicle,fare,ride_date,ride_time,passengers,luggage,customer_name,phone,email,payment,status,created_at FROM soft_ride_bookings ORDER BY created_at DESC')->fetchAll();$messages=db()->query('SELECT id,name,email,subject,message,created_at FROM soft_ride_messages ORDER BY created_at DESC')->fetchAll();respond(200,['bookings'=>$bookings,'messages'=>$messages]);}catch(Throwable $e){error_log($e);respond(500,['error'=>'Could not load admin data.']);}
